pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(address recipient, uint256 amount) internal {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        bool secondReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assertTrue(!(!firstReverted && !secondReverted));
    }

    function testFuzz_run(address recipient, uint256 amount) public {
        vm.assume(recipient.code.length == 0 && uint160(recipient) > 0xffff && recipient != address(this) && recipient != address(c) && recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(recipient, amount);
    }

    receive() external payable {}
}
